    public static final int MAX_GUARANTEE_MINUTES = 720;

    private static final String OP_CONN_REGISTER = "CONN_REGISTER";
    private static final String OP_CONN_CANCEL = "CONN_CANCEL";
    private static final String OP_BATCH_GUARANTEE = "BATCH_GUARANTEE";

    private final PlanRepository planRepo;
    private final ConnectionRepository connRepo;
    private final IdempotencyRepository idemRepo;
    private final ObjectMapper objectMapper;
    private final TransactionTemplate tx;
    private final Clock clock;
```

Methods:

**register(ConnectionRegisterRequest req)**:
```java
boolean crossMidnight = Boolean.TRUE.equals(req.crossMidnight());
int guarantee = req.guaranteeMinutes();
if (guarantee < MIN || guarantee > MAX) throw 422 GUARANTEE_MINUTES_INVALID with details actualMinutes/min/max
if (req.predecessorKey().equals(req.successorKey())) throw badRequest
String hash = sha256(...);
replay check (ConnectionView.class)
tx:
  planRepo.acquirePublishLock();  // 全局锁，与发布/改签/批量保障统一串行顺序
  DayPlan pred = findByKeyForUpdate(predKey) or 404
  DayPlan succ = findByKeyForUpdate(succKey) or 404
  if pred.status == CANCELLED || succ.status == CANCELLED → 422 CONNECTION_PLAN_CANCELLED
  if pred.status != PUBLISHED || succ.status != PUBLISHED → 409 PLAN_STATE_CONFLICT
  // op date
  if (pred.opDate().equals(succ.opDate())) { /* ok */ }
  else if (succ.opDate().equals(pred.opDate().plusDays(1)) && crossMidnight) { /* ok */ }
  else → 422 CONNECTION_OP_DATE_INVALID (details: predecessorOpDate, successorOpDate, crossMidnight)
  // occupancies
  List<Occupancy> predOcc = planRepo.findOccupancies(pred.id);
  List<Occupancy> succOcc = planRepo.findOccupancies(succ.id);
  Occupancy predLast = max by endUtc; Occupancy succFirst = min by startUtc;
  // station continuity
  if (!req.transferStation().equals(predLast.toStation()) || !req.transferStation().equals(succFirst.fromStation()))
     → 422 CONNECTION_STATION_GAP details: transferStation, predecessorArrivalStation, successorDepartureStation
  // timing
  Instant requiredStart = predLast.endUtc + guarantee min
  long actualMinutes = Duration.between(predLast.endUtc, succFirst.startUtc).toMinutes();
  if (succFirst.startUtc.isBefore(requiredStart)) → 422 CONNECTION_GAP_INSUFFICIENT details requiredMinutes, actualMinutes, deficitMinutes
  // duplicate
  if (connRepo.findActiveByPair(pred.id, succ.id).isPresent()) → 409 CONNECTION_EXISTS
  insert; view; idem
catch DuplicateKeyException → resolveDuplicate
```

**cancelConnection(long connectionId, String requestKey)**:
```java
hash = sha256(OP_CONN_CANCEL + id)
replay
tx:
  planRepo.acquirePublishLock();
