// distinct check
if (new HashSet<>(req.scheduleKeys()).size() != req.scheduleKeys().size()) → 400
hash; replay (BatchGuaranteeResponse.class)
tx:
  planRepo.acquirePublishLock();
  List<DayPlan> plans = new ArrayList<>();
  for key: planRepo.findByKeyForUpdate(key) or 404
  // checks
  for plan:
    if plan.status != PUBLISHED → 409 PLAN_STATE_CONFLICT
    if (!RISK.equals(plan.connectionRisk)) → 422 PLAN_NOT_AT_RISK
  // occupancies
  Map<Long, List<Occupancy>> occByPlan
  for plan: first start must be after now → else 422 PLAN_ALREADY_STARTED (details scheduleKey, firstStartUtc, nowUtc)
  // compute shifts, process in order of current first start
  plans sorted by firstStart
  Map<Long, List<Occupancy>> shifted = new HashMap<>();
  Map<Long, Long> shiftMillis
  for plan in sorted:
    List<Occupancy> occ = occByPlan.get(plan.id)
    // required start from active connections
    Instant required = null; Connection binding = null; long maxDeficit = 0;
    for conn in connRepo.findActiveBySuccessor(plan.id):
       Instant predEnd = lastEnd(resolveOccupancies(conn.predecessorPlanId))  // shifted if in batch else db
       Instant req = predEnd + guarantee
       actual = firstStart(occ) - predEnd (minutes)
       deficit = guarantee - actual
       if required == null || req.isAfter(required) { required = req; binding = conn; }
       maxDeficit = max(maxDeficit, deficit)
    // note: plan is AT_RISK so there is at least one connection; but connections may all be satisfied now? still proceed with shift = max(0,...)
    long shift = required == null ? 0 : max(0, required - firstStart)
    // feasibility loop
    loop:
